<script lang="ts">
 import type {HumanUatItem,HumanUatRecord,WorkPackageEntityContext} from '../../lib/model/entityTypes.ts';
 import {canPassHumanUat,parseOwnerHumanUatPlan} from '../../lib/humanUat.ts';
 import {formatOwnerLocalTime,OWNER_TIME_FALLBACK} from '../../lib/ownerTime.ts';
 export let context:WorkPackageEntityContext; export let repository='local'; export let record:HumanUatRecord|null=null; export let onSave:(record:HumanUatRecord)=>void|Promise<void>=()=>{}; export let onNavigate:(tab:string)=>void=()=>{};
 const manualChecklist:HumanUatItem[]=[{id:'manual-login',title:'用户登录与登出',description:'',state:'PENDING'},{id:'manual-work-package',title:'创建工作包',description:'',state:'PENDING'},{id:'manual-lifecycle',title:'生命周期状态正确',description:'',state:'PENDING'},{id:'manual-files',title:'文件上传与预览',description:'',state:'PENDING'},{id:'manual-permissions',title:'权限控制校验',description:'',state:'PENDING'}];
 let items:HumanUatItem[]=[];
 let draftItems:HumanUatItem[]=[]; let draftNote=''; let dirty=false; let lastSourceKey='';
 $: plan=parseOwnerHumanUatPlan(context.formalWorkPackage?.sections['Owner Human UAT Plan']??'');
 $: items=(plan.length?plan:manualChecklist).map(item=>record?.items.find(value=>value.id===item.id)??item);
 $: sourceKey=JSON.stringify(items)+`|${record?.overallNote??''}|${record?.status??''}`;
 $: if(sourceKey!==lastSourceKey&&!dirty){draftItems=items.map(item=>({...item}));draftNote=record?.overallNote??'';lastSourceKey=sourceKey}
 $: rounds=plan.filter((item,index,array)=>array.findIndex(value=>value.roundId===item.roundId)===index).map(item=>({id:item.roundId,title:item.round,order:item.order,items:items.filter(value=>value.roundId===item.roundId)}));
 $: currentRoundIndex=Math.max(0,Math.min(rounds.length-1,rounds.findIndex(round=>round.items.some(item=>item.state!=='PASS'&&item.state!=='N_A'))<0?rounds.length-1:rounds.findIndex(round=>round.items.some(item=>item.state!=='PASS'&&item.state!=='N_A'))));
 $: currentRound=rounds[currentRoundIndex]??{id:'',title:'',order:0,items:[]}; $: completedRounds=rounds.filter(round=>round.items.length>0&&round.items.every(item=>item.state==='PASS'||item.state==='N_A')).length;
 $: lifecycleUatStatus=context.lifecycle.stages.find(stage=>stage.id==='HUMAN_UAT')?.status??'NOT_STARTED';
 $: enteredUat=['WAITING_UAT','PASS','BLOCKED','FAILED'].includes(lifecycleUatStatus)||['IN_PROGRESS','NEEDS_REMEDIATION','PASS'].includes(record?.status??'');
 $: editable=context.lifecycle.currentStage==='HUMAN_UAT'||lifecycleUatStatus==='WAITING_UAT';
 $: currentStatus=record?.status==='PASS'||lifecycleUatStatus==='PASS'?'PASS':record?.status==='NEEDS_REMEDIATION'||lifecycleUatStatus==='BLOCKED'||lifecycleUatStatus==='FAILED'?'NEEDS_REMEDIATION':lifecycleUatStatus==='WAITING_UAT'||record?.status==='IN_PROGRESS'?'IN_PROGRESS':'NOT_STARTED';
 $: decisionModeLabel=record?.decisionMode==='OWNER_OVERRIDE_PASS'?'Owner 直接通过':currentStatus==='PASS'&&!record?'历史 Owner 通过':'逐项验收';
 $: passedWithoutChecklist=currentStatus==='PASS'&&(items.length===0||items.every(item=>item.state==='PENDING'));
 $: closed=context.lifecycle.currentStage==='CLOSED';
 $: completionTime=record?.finalDecisionAt??record?.updatedAt??record?.createdAt;
 $: historicalItems=items;
 function updateItem(item:HumanUatItem,state:HumanUatItem['state']){draftItems=draftItems.map(value=>value.id===item.id?{...value,state}:value);dirty=true}
 function updateActualResult(item:HumanUatItem,event:Event){const note=(event.currentTarget as HTMLInputElement).value;draftItems=draftItems.map(value=>value.id===item.id?{...value,note,ownerNote:note}:value);dirty=true}
 function makeRecord(nextItems=items,overallNote=record?.overallNote??'',status=record?.status??'NOT_STARTED',decisionMode=record?.decisionMode):HumanUatRecord{return {repository,workPackageId:context.id,entityType:'work_package',status,ownerLabel:'Owner',items:nextItems,overallNote,decision:status==='PASS'?'PASS':undefined,decisionMode,decisionCode:decisionMode,createdAt:record?.createdAt??new Date().toISOString(),updatedAt:new Date().toISOString(),finalDecisionAt:status==='PASS'?new Date().toISOString():record?.finalDecisionAt,source:'formal Owner Human UAT Plan'}}
 function saveProgress(){onSave(makeRecord(draftItems,draftNote,draftItems.some(item=>item.state!=='PENDING')?'IN_PROGRESS':'NOT_STARTED'));dirty=false}
 function remediate(){if(!draftItems.some(item=>item.state==='FAIL')&&!draftNote.trim()&&!draftItems.some(item=>item.note?.trim()))return;onSave(makeRecord(draftItems,draftNote,'NEEDS_REMEDIATION'));dirty=false}
 function canPassDraft(){return canPassHumanUat(draftItems)&&(!plan.length||draftItems.filter(item=>item.state==='PASS').every(item=>Boolean(item.note?.trim())))}
 function pass(){if(!editable)return;if(!plan.length){if(!window.confirm('当前没有正式逐项验收清单，确认人工验收通过？'))return;onSave(makeRecord(draftItems,draftNote,'PASS','ITEMIZED_PASS'));dirty=false;return}if(!canPassDraft())return;onSave(makeRecord(draftItems,draftNote,'PASS','ITEMIZED_PASS'));dirty=false}
 function viewEvidence(){onNavigate('证据')}
 function viewRunResults(){onNavigate('运行')}
 function viewInstruction(){onNavigate('运行')}
 function overall(event:Event){draftNote=(event.currentTarget as HTMLTextAreaElement).value;dirty=true}
 function historicalActualResult(item:HumanUatItem){return item.note??(item.state==='PASS'?'已完成':item.state==='N_A'?'不适用':'未记录')}
</script>
<section class="uat-workspace" data-testid="human-uat-workspace">
 <div class="section-label"><span>人工验收</span><small>Owner Human UAT</small></div>
 <div class="uat-action-bar" data-testid="uat-top-action-bar"><div class="uat-action-group uat-action-read"><button class="action" onclick={viewEvidence}>📎 验收证据</button><button class="action" onclick={viewRunResults}>▶️ 运行结果</button><button class="action" onclick={viewInstruction}>📄 原始指令</button></div>{#if editable}<div class="uat-action-group uat-action-mutate"><button class="action" onclick={saveProgress}>💾 保存进度</button><button class="action remediation" disabled={!draftItems.some(item=>item.state==='FAIL')&&!draftNote.trim()&&!draftItems.some(item=>item.note?.trim())} onclick={remediate}>↩️ 退回整改</button><button class="action primary" disabled={plan.length>0&&!canPassDraft()} onclick={pass}>✅ 通过UAT</button></div>{/if}{#if dirty}<small class="uat-unsaved-hint">有未保存修改</small>{/if}{#if closed}<small class="uat-readonly-badge">已完成 · 只读</small>{/if}</div>
 {#if closed}<div class="uat-summary uat-history-summary"><div><span>验收状态</span><b class:uat-status-active={currentStatus==='IN_PROGRESS'} class:uat-status-pass={currentStatus==='PASS'} class:uat-status-fail={currentStatus==='NEEDS_REMEDIATION'}>{currentStatus==='PASS'?'已通过':currentStatus==='IN_PROGRESS'?'验收中':currentStatus==='NEEDS_REMEDIATION'?'未通过':'待验收'}</b></div><div><span>验收进度</span><b>{passedWithoutChecklist?`${items.filter(item=>item.state==='PASS'||item.state==='N_A').length} / ${items.length}`:`${items.filter(item=>item.state==='PASS'||item.state==='N_A').length} / ${items.length}`}</b></div><div data-testid="human-uat-decision-mode"><span>验收方式</span><b>{decisionModeLabel}</b></div><div><span>完成时间</span><b>{completionTime?formatOwnerLocalTime(completionTime):OWNER_TIME_FALLBACK}</b></div></div>{:else}<div class="uat-summary"><div><span>验收状态</span><b class:uat-status-active={currentStatus==='IN_PROGRESS'} class:uat-status-pass={currentStatus==='PASS'} class:uat-status-fail={currentStatus==='NEEDS_REMEDIATION'}>{currentStatus==='PASS'?'已通过':currentStatus==='IN_PROGRESS'?'验收中':currentStatus==='NEEDS_REMEDIATION'?'未通过':'待验收'}</b></div><div><span>验收进度</span><b>{passedWithoutChecklist?'已通过':`${items.filter(item=>item.state==='PASS').length} / ${items.length}`}</b></div><div data-testid="human-uat-decision-mode"><span>验收方式</span><b>{decisionModeLabel}</b></div></div>{/if}
 {#if !enteredUat}<p class="uat-not-ready">尚未进入人工验收阶段。当前仅提供验收清单预览。</p>{/if}
 {#if closed}<div class="uat-checklist uat-history-checklist"><h3>验收清单</h3><div class="uat-history-table" data-testid="history-uat-checklist"><div class="uat-history-row uat-history-head"><strong>检查项</strong><strong>预期结果</strong><strong>实际结果</strong><strong>状态</strong></div>{#each historicalItems as item}<div class="uat-history-row"><span>{item.title}</span><span>{item.passCriteria??item.description??'—'}</span><span>{historicalActualResult(item)}</span><strong class:uat-history-pass={item.state==='PASS'||item.state==='N_A'}>{item.state==='PASS'?'✓ 已通过':item.state==='N_A'?'— 不适用':item.state==='FAIL'?'✕ 未通过':'待验证'}</strong></div>{/each}</div></div>{:else}<div class="uat-checklist uat-open-checklist"><h3>验收清单</h3><div class="uat-history-table" data-testid="open-uat-checklist"><div class="uat-history-row uat-history-head"><strong>检查项</strong><strong>预期结果</strong><strong>实际结果</strong><strong>状态</strong></div>{#each draftItems as item}<div class="uat-history-row"><span>{item.title}</span><span>{item.passCriteria??item.description??'—'}</span><input class="uat-actual-result" aria-label={`${item.title} 实际结果`} maxlength="160" value={item.note??''} disabled={!editable} oninput={(event)=>updateActualResult(item,event)}/><label class="uat-status-check"><input type="checkbox" checked={item.state==='PASS'} disabled={!editable} onchange={()=>updateItem(item,item.state==='PASS'?'PENDING':'PASS')}/><span>{item.state==='PASS'?'✓ 通过':'待验证'}</span></label></div>{/each}</div></div>{/if}
 <div class="uat-findings"><h3>{closed?'问题记录（历史）':'问题记录'}</h3>{#each items.filter(item=>item.state==='FAIL') as item}<p><strong>{item.title}</strong>：{item.note??'需补充 Owner 备注'}</p>{:else}<p>{closed?'未记录到问题。':'暂无已记录问题。'}</p>{/each}</div>
 {#if closed}<div class="uat-history-note"><h3>Owner 备注（历史）</h3><p>{record?.overallNote?.trim()||'未记录 Owner 备注。'}</p><small>记录时间：{completionTime?formatOwnerLocalTime(completionTime):OWNER_TIME_FALLBACK}</small></div>{:else}<label class="uat-overall-note">Owner 备注<textarea maxlength="2000" value={draftNote} disabled={!editable} oninput={overall}></textarea></label>{/if}
</section>
